for(int i=0;i<n;i++){opts[i]=configs[i%37];auto a=opts[i];double S=a.spot,K=a.strike,q=a.q,r=a.r,T=a.t,v=a.vol;double sd=v*sqrt(T),d1=(log(S/K)+(r-q+0.5*v*v)*T)/sd,d2=d1-sd,N1=0.5*(1+erf(d1/sqrt(2.))),N2=0.5*(1+erf(d2/sqrt(2.)));double call=S*exp(-q*T)*N1-K*exp(-r*T)*N2;expected[i]=a.type==PUT?call-S*exp(-q*T)+K*exp(-r*T):call;}
optionInputStruct *input;float *output;cudaMalloc(&input,n*sizeof(optionInputStruct));cudaMalloc(&output,n*4);cudaMemcpy(input,opts.data(),n*sizeof(optionInputStruct),cudaMemcpyHostToDevice);

